eparately."}],"publicSummary":"Official source status: final. Every race, discard and scoring code retained. Does not count for Singapore national rankings.","importedEntryCount":15,"deferredEntryCount":0,"profilePreflight":[{"id":"6b42e276-4836-4f99-bb40-0542ee7b5dde","club":"YRAT","name":"Kanyapat Pisoottiwong","gender":"Female","handle":"kanyapat-pisoottiwong-6sr2pun","birthYear":2015,"sailNumber":"996","nationality":"THA","sailNumberIlca4":null},{"id":"1e889e8d-dac7-4f91-a542-733afdadf74a","club":"YRAT","name":"Natkritta Boonsang","gender":"Female","handle":"natkritta-boonsang-sbmfkm6","birthYear":2017,"sailNumber":"1478","nationality":"THA","sailNumberIlca4":null},{"id":"57afc0b5-a27a-486a-84e1-ef59120d492c","club":"Imported official result","name":"Pavarisa Kaewlek","gender":"F","handle":"asian-unk-pavarisa-k-ab0677","birthYear":null,"sailNumber":"1953","nationality":"THA","sailNumberIlca4":null},{"id":"1b6eb642-a669-4bdc-8f1f-1d01d7b7e41e","club":"ACDC.SC","name":"Chattapat Somprasong","gender":"Male","handle":"chattapat-somprasong-yhx7ypz","birthYear":2015,"sailNumber":"1234","nationality":"THA","sailNumberIlca4":null},{"id":"8c67fc05-1caf-434c-88a5-71ad35c4fba0","club":"YRAT","name":"Setthawit Yodmanee","gender":"Male","handle":"setthawit-yodmanee-jdvl8az","birthYear":2017,"sailNumber":"878","nationality":"THA","sailNumberIlca4":null},{"id":"768b3680-930d-4a1c-82d9-5dea9717701a","club":"SSA","name":"Dhan Chintanaseri Suksantinunt","gender":"Male","handle":"dhan-chintanaseri-suksantinunt-3pq1rbq","birthYear":2016,"sailNumber":"1593","nationality":"THA","sailNumberIlca4":null},{"id":"8b594c37-db52-4549-a765-f51fd619238d","club":"ACDC.SC","name":"Netchanok Chatawattanasopakun","gender":"Female","handle":"netchanok-chatawattanasopakun-b63j9ly","birthYear":2015,"sailNumber":"1644","nationality":"THA","sailNumberIlca4":null},{"id":"976342b7-69ec-4200-8e46-684855939591","club":"YRAT","name":"Pimpisa Devahastin Na Ayudhya","gender":"Female","handle":"pimpisa-devaha